if(lesson.startsWith('2.')&&typeof answer==='number'&&expression){let display=fmt(answer);for(let den=1;den<=10000;den++){const top=Math.round(answer*den);if(Math.abs(top/den-answer)<1e-10){display=fraction(top,den);break;}}solution=expression.replaceAll('*','×')+'＝'+display+unit;}
if(!text||typeof answer==='number'&&!Number.isFinite(answer))throw Error('题型生成失败');return {id:`bank-v1-${profile}-${lesson}-${i}`,lesson,text,answer,unit,expression,options,rule,hint,solution,diagram,type:options?'choice':'number',kind:['基础计算','情境应用','思考拓展'][mode]};
